def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    bal = {}
    frozen = set()
    stack = []  # entries: undo information for each successful non-undo op
    rejected = []

    def valid_amount(s):
        return len(s) > 0 and all(c in "0123456789" for c in s)

    for i, op in enumerate(ops):
        t = op.split(" ")
        verb = t[0] if t else ""
        ok = False
        if verb == "open" and len(t) == 3:
            a, n = t[1], t[2]
            if valid_amount(n) and a not in bal:
                bal[a] = int(n)
                stack.append(("open", a))
                ok = True
        elif verb == "deposit" and len(t) == 3:
            a, n = t[1], t[2]
            if valid_amount(n) and int(n) > 0 and a in bal:
                v = int(n)
                bal[a] += v
                stack.append(("dep", a, v))
                ok = True
        elif verb == "withdraw" and len(t) == 3:
            a, n = t[1], t[2]
            if valid_amount(n) and int(n) > 0 and a in bal and a not in frozen and bal[a] >= int(n):
                v = int(n)
                bal[a] -= v
                stack.append(("dep", a, -v))
                ok = True
        elif verb == "transfer" and len(t) == 4:
            a, b, n = t[1], t[2], t[3]
            if (valid_amount(n) and int(n) > 0 and a != b and a in bal and b in bal
                    and a not in frozen and bal[a] >= int(n)):
                v = int(n)
                bal[a] -= v
                bal[b] += v
                stack.append(("tr", a, b, v))
                ok = True
        elif verb == "freeze" and len(t) == 2:
            a = t[1]
            if a in bal and a not in frozen:
                frozen.add(a)
                stack.append(("freeze", a))
                ok = True
        elif verb == "unfreeze" and len(t) == 2:
            a = t[1]
            if a in bal and a in frozen:
                frozen.discard(a)
                stack.append(("unfreeze", a))
                ok = True
        elif verb == "undo" and len(t) == 1:
            if stack:
                e = stack.pop()
                k = e[0]
                if k == "open":
                    del bal[e[1]]
                    frozen.discard(e[1])
                elif k == "dep":
                    bal[e[1]] -= e[2]
                elif k == "tr":
                    bal[e[1]] += e[3]
                    bal[e[2]] -= e[3]
                elif k == "freeze":
                    frozen.discard(e[1])
                elif k == "unfreeze":
                    frozen.add(e[1])
                ok = True
        if not ok:
            rejected.append(i)
    return bal, rejected
